import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"Escalation · 升级","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/escalation.md","filePath":"strategies/escalation.md"}'),o={name:"strategies/escalation.md"};function i(n,t,s,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="escalation-·-升级" tabindex="-1">Escalation · 升级 <a class="header-anchor" href="#escalation-·-升级" aria-label="Permalink to &quot;Escalation · 升级&quot;">​</a></h1><p>先由起始模型执行，Judge 检查未交付候选；需要接管时丢弃候选，由指定模型继续原生 Agent 循环。 每任务最多一次接管，接管后锁定该模型，不再调用 Judge。</p><h2 id="四种判别与动作" tabindex="-1">四种判别与动作 <a class="header-anchor" href="#四种判别与动作" aria-label="Permalink to &quot;四种判别与动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>判别／情况</th><th>行为</th></tr></thead><tbody><tr><td>PROCEED：合格或正常工具探索</td><td>放行文本与工具调用，清零连续停滞</td></tr><tr><td>DEFECT：明确违反任务或与已有证据矛盾</td><td>立即丢弃，由接管模型生成</td></tr><tr><td>STALL：工具过程疑似停滞</td><td>默认连续两次后接管；首次可继续</td></tr><tr><td>STALL：已经准备结束</td><td>立即接管，不等待不存在的下一轮</td></tr><tr><td>UNCERTAIN／本地已知超容量</td><td>使用合格接管模型，不换 Judge 后端</td></tr><tr><td>接管已发生</td><td>使用接管模型并标记“接管后未追加审核”</td></tr></tbody></table><p>正常搜索、合理测试失败、正确澄清和如实说明权限限制不直接判为缺陷或停滞。 认证、传输、未知用量或进程崩溃属于故障，停止调用，不借换模型重试。</p><h2 id="必要设置" tabindex="-1">必要设置 <a class="header-anchor" href="#必要设置" aria-label="Permalink to &quot;必要设置&quot;">​</a></h2><p>起始模型与接管模型、各自推理等级、独立 Judge、停滞次数与审核期限。 起始与接管配置完全相同不能形成有效接管，预检阻止新版配置启用。</p><p>官方 Jev、轻量 LLM 与本地 Laya 使用独立于 Task 的回复判别合同。 选择官方 Jev 后，在渠道设置里核对 OpenRouter 和信任策略；本地当前仍标实验。</p><h2 id="输出与历史" tabindex="-1">输出与历史 <a class="header-anchor" href="#输出与历史" aria-label="Permalink to &quot;输出与历史&quot;">​</a></h2><p>起始候选的正文、推理块和工具调用全部缓冲。 丢弃候选不进入正常历史，其中工具不会执行；接管使用原请求及已接受历史。 接管后的输出允许流式交付，已经释放的文字不能被后来判别悄悄替换。</p><h2 id="费用与轨迹" tabindex="-1">费用与轨迹 <a class="header-anchor" href="#费用与轨迹" aria-label="Permalink to &quot;费用与轨迹&quot;">​</a></h2><p>接管前保护“起始执行＋一次 Judge＋可能的接管”路径；真正发生的调用分别结算。 未派发额度释放，未知用量保留。接管后每轮只预留一次执行，不追加审核费用。 轨迹显示原始判别、证据、停滞计数、接管原因、接受／丢弃、真实模型及等待时间。 正常不确定也会接管，因此需观察不必要接管带来的费用与延迟。</p>',12)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
